from pathlib import Path
import json,base64,zipfile
R=Path(__file__).resolve().parent;O=R/'output'
three=(R.parent/'chassis_fr4_v1/output/preview/three.min.js').read_text(encoding='utf-8')
scene=(O/'preview/scene.json').read_text(encoding='utf-8')
import cadquery as cq
s=cq.importers.importStep(str(O/'step/01_adapter_center_84x64_M3.step')).val();v,f=s.tessellate(.12,.16)
local=json.dumps([{'name':'adapter','color':'#e58c39','group':'adapter','v':[p.toTuple() for p in v],'f':f}])
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>V2 中央槽孔 PCB 转接板</title>
<style>*{box-sizing:border-box}body{margin:0;font:15px system-ui,"Microsoft YaHei",sans-serif;background:#edf2f4;color:#213e49}header{padding:22px 28px;background:white;border-bottom:1px solid #d0dbe0}h1{font-size:24px;margin:0 0 8px}p{line-height:1.7;margin:8px 0}main{display:grid;grid-template-columns:1fr 310px;min-height:80vh}.view{position:relative;min-height:650px}canvas{width:100%;height:100%;position:absolute;touch-action:none}.tools{position:absolute;z-index:2;top:18px;left:18px;display:flex;gap:7px;flex-wrap:wrap}button{padding:9px 12px;background:white;border:1px solid #b7c9cf;border-radius:5px;color:#213e49;cursor:pointer}button:hover{background:#dbebe8}aside{background:white;padding:25px;border-left:1px solid #d0dbe0}h2{font-size:17px}dl{display:grid;grid-template-columns:1fr auto;gap:12px}dd{margin:0}small{line-height:1.8;color:#647e89}img{max-width:100%}.hint{position:absolute;bottom:18px;left:22px;color:#647e89}.error{display:none;padding:110px 20px 20px}@media(max-width:850px){main{display:block}aside{border:0}.view{min-height:520px}}</style>
<header><h1>V2 · 电路板居中安装在底板下方</h1><p>PCB 90 × 70 mm · 四孔 84 × 64 mm · M3 · 连接中部四个 80 × 60 mm 槽孔</p></header>
<main><div class="view"><canvas id="view"></canvas><div class="tools"><button onclick="mode('part')">转接板单件</button><button onclick="mode('assembly')">中央装配</button><button onclick="preset('iso')">斜视</button><button onclick="preset('bottom')">底视</button><button onclick="preset('top')">顶视</button><button onclick="preset('side')">侧视</button><button onclick="toggleDeck()">底盘显示 / 隐藏</button></div><div class="hint">拖动旋转 · 滚轮缩放 · 橙色转接板 · 绿色电路板 · 蓝灰色原摆架底座</div><div id="fallback" class="error"><p>当前环境无法启用三维渲染，显示静态预览。</p><img src="data:image/png;base64,__PNG__"></div></div>
<aside><h2>中央四槽固定</h2><dl><dt>转接板平面外形</dt><dd>100 × 104 mm</dd><dt>主板厚度</dt><dd>4 mm</dd><dt>一体支柱</dt><dd>高 6 mm</dd><dt>中央开窗</dt><dd>44 × 64 mm</dd><dt>槽中心距</dt><dd>80 × 60 mm</dd><dt>底盘原槽尺寸</dt><dd>18 × 3.5 mm</dd><dt>底盘侧隔柱</dt><dd>Ø8 × 10 × 4件</dd><dt>顶部跨槽垫圈</dt><dd>Ø9 mm × 4件</dd><dt>转接板通孔</dt><dd>Ø3.4 mm</dd></dl><hr><p>两板中心重合，连接底盘 X=±40、Y=±30 的四个槽。PCB 沿车长 70、沿车宽 90。</p><p>原中央电池占位与 PCB 重合，电池需另行布置。</p><small>板厚暂按 1.6 mm，PCB 朝底盘一面留 6 mm 间隙。顶部 Ø9 垫圈距原摆架底座最近 0.5 mm。元件、插头和实际离地间隙尚需实物核对。</small><p><a href="dimensions.svg">查看尺寸图</a></p></aside></main><script>__THREE__</script>
<script>const assembled=__SCENE__,single=__LOCAL__;let renderer,scene,camera,group,current='part',yaw=-.9,pitch=.68,radius=245,drag=null,deckVisible=true,target=new THREE.Vector3(0,0,4);const canvas=document.getElementById('view');
function build(data){if(group){scene.remove(group);group.traverse(o=>{o.geometry?.dispose();o.material?.dispose()})}group=new THREE.Group();for(const o of data){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(o.v.flat(),3));g.setIndex(o.f.flat());g.computeVertexNormals();const mesh=new THREE.Mesh(g,new THREE.MeshStandardMaterial({color:o.color,metalness:.08,roughness:.68,side:THREE.DoubleSide}));mesh.userData.kind=o.group;const edge=new THREE.LineSegments(new THREE.EdgesGeometry(g,28),new THREE.LineBasicMaterial({color:0x2d4651,transparent:true,opacity:.28}));mesh.add(edge);group.add(mesh)}scene.add(group)}
function draw(){if(!renderer)return;const r=canvas.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();camera.up.set(0,0,1);const cp=Math.cos(pitch);camera.position.set(target.x+radius*cp*Math.cos(yaw),target.y+radius*cp*Math.sin(yaw),target.z+radius*Math.sin(pitch));camera.lookAt(target);group.children.forEach(m=>{m.visible=m.userData.kind!=='chassis'||deckVisible});renderer.render(scene,camera);canvas.dataset.rendered='true'}
function mode(m){current=m;build(m==='part'?single:assembled);target.set(m==='part'?0:0,0,m==='part'?4:-8);radius=m==='part'?245:570;preset('iso')}
function preset(v){yaw=-.9;pitch=current==='part'?.68:-.55;if(v==='bottom'){yaw=-Math.PI/2;pitch=-1.56}if(v==='top'){yaw=-Math.PI/2;pitch=1.56}if(v==='side'){yaw=-Math.PI/2;pitch=.015}draw()}
function toggleDeck(){deckVisible=!deckVisible;draw()}
try{renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));scene=new THREE.Scene();scene.add(new THREE.HemisphereLight(0xffffff,0x556774,2.3));for(const pos of [[-180,-250,400],[100,100,-300]]){const light=new THREE.DirectionalLight(0xffffff,1.9);light.position.set(...pos);scene.add(light)}camera=new THREE.PerspectiveCamera(36,1,.1,5000);mode('part');canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(drag){yaw-=(e.clientX-drag[0])*.008;pitch=Math.max(-1.56,Math.min(1.56,pitch+(e.clientY-drag[1])*.008));drag=[e.clientX,e.clientY];draw()}};canvas.onpointerup=()=>drag=null;canvas.onpointercancel=()=>drag=null;canvas.addEventListener('wheel',e=>{e.preventDefault();radius=Math.max(90,Math.min(1400,radius*Math.exp(e.deltaY*.001)));draw()},{passive:false});new ResizeObserver(draw).observe(canvas.parentElement);window.adapterViewer={mode,preset,draw}}catch(e){document.getElementById('fallback').style.display='block';canvas.style.display='none'}</script></html>'''
html=html.replace('__THREE__',three).replace('__SCENE__',scene).replace('__LOCAL__',local).replace('__PNG__',base64.b64encode((O/'preview/adapter_and_assembly.png').read_bytes()).decode())
html=html.replace("mode('part');canvas.onpointerdown", "mode('assembly');canvas.onpointerdown")
(O/'preview/adapter_viewer.html').write_text(html,encoding='utf-8')
# Root copy remains standalone; embed dimensions link as a data URI as well.
svg=base64.b64encode((O/'preview/dimensions.svg').read_bytes()).decode()
standalone=html.replace('href="dimensions.svg"',f'href="data:image/svg+xml;base64,{svg}"')
(R.parent/'PCB底部转接板_中央四槽_V2_独立预览.html').write_text(standalone,encoding='utf-8')
# Update the previously shared generic preview to the corrected center-mounted design.
(R.parent/'PCB底部转接板_84x64_M3_独立预览.html').write_text(standalone,encoding='utf-8')
with zipfile.ZipFile(R.parent/'PCB底部转接板_中央四槽_84x64_M3_V2.zip','w',zipfile.ZIP_DEFLATED) as z:
    for f in R.rglob('*'):
        if f.is_file() and '__pycache__' not in f.parts: z.write(f,f.relative_to(R.parent))
print('Standalone viewer and ZIP packaged.')
